pub fn header() -> String {
    String::from(
        "<!-- generated by cargo xtask systems. edit docs/systems/graph/ or docs/systems/state-machines.toml instead. -->\n\n",
    )
}

pub fn cell(value: &str) -> String {
    value.replace('|', "\\|").replace(['\n', '\r'], " ")
}

pub fn label(value: &str) -> String {
    let value = value.replace("<br/>", "\u{0}").replace("<br>", "\u{0}");
    let mut out = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '\u{0}' => out.push_str("<br/>"),
            '"' => out.push('\''),
            '|' => out.push('/'),
            '{' => out.push('('),
            '}' => out.push(')'),
            '<' | '>' | '\n' | '\r' => out.push(' '),
            _ => out.push(character),
        }
    }
    out
}

pub fn id(prefix: &str, value: &str) -> String {
    format!("{prefix}_{}", sanitize(value))
}

fn sanitize(value: &str) -> String {
    let mut out = String::new();
    for character in value.chars() {
        if character.is_ascii_alphanumeric() {
            out.push(character.to_ascii_lowercase());
        } else {
            out.push('_');
        }
    }
    if out.is_empty() || out.starts_with(|character: char| character.is_ascii_digit()) {
        out.insert(0, 'n');
    }
    out
}

pub fn node_id(value: &str) -> String {
    id("n", value)
}

pub fn state_id(value: &str) -> String {
    id("s", value)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn markdown_cells_escape_pipes_and_newlines() {
        assert_eq!(cell("a|b\nc"), "a\\|b c");
    }

    #[test]
    fn mermaid_labels_escape_quotes_and_newlines() {
        assert_eq!(label("a\"b\nc"), "a'b c");
    }

    #[test]
    fn mermaid_labels_escape_structural_characters() {
        assert_eq!(label("a|b{\"c\"}<br/>d"), "a/b('c')<br/>d");
    }

    #[test]
    fn ids_are_stable_and_safe() {
        assert_eq!(node_id("RT.lifecycle"), "n_rt_lifecycle");
        assert_eq!(state_id("in_call"), "s_in_call");
        assert_eq!(node_id("1st"), "n_n1st");
    }
}
